head.b:skin:
/* ============================================
   1. VARIABLES
   ============================================ */
:root{
  --primary:#c8102e;
  --primary-dark:#a00d24;
  --accent:#0a0a0a;
  --text:#1f2024;
  --muted:#6b7280;
  --bg:#ffffff;
  --surface:#f5f6f8;
  --border:#e7e8ec;
  --header-bg:#0d0f14;
  --header-fg:#ffffff;
  --radius:10px;
  --radius-sm:6px;
  --maxw:1280px;
  --shadow-sm:0 1px 3px rgba(0,0,0,.08);
  --shadow:0 4px 18px rgba(0,0,0,.10);
  --shadow-lg:0 10px 40px rgba(0,0,0,.16);
  --font-sans:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;
  --font-serif:Georgia,'Times New Roman',serif;
  --transition:.25s ease;
}

/* Variable declarations for Blogger theme designer */
<Variable name="keycolor" description="Main Color" type="color" default="#c8102e" value="#c8102e"/>
<Variable name="accent.color" description="Accent Color" type="color" default="#0a0a0a" value="#0a0a0a"/>
<Variable name="breaking.news.bg" description="Breaking News Background" type="color" default="#c8102e" value="#c8102e"/>

/* ============================================
   2. RESET
   ============================================ */
*,*::before,*::after{box-sizing:border-box}
html{-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0}
article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section{display:block}
img,svg{max-width:100%;height:auto}
button,input,optgroup,select,textarea{font:inherit;color:inherit;margin:0}
button{cursor:pointer;overflow:visible}
a{background:transparent;color:var(--primary);text-decoration:none;transition:color var(--transition)}
a:hover{color:var(--primary-dark);text-decoration:underline}
ul,ol{margin:0;padding:0;list-style:none}
figure{margin:0}
img{border:0}

/* ============================================
   3. BASE TYPOGRAPHY
   ============================================ */
body{
  background:var(--bg);
  color:var(--text);
  font-family:var(--font-sans);
  font-size:16px;
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
h1,h2,h3,h4,h5,h6{font-family:var(--font-serif);font-weight:700;line-height:1.25;color:var(--accent);margin:0 0 .5em}
p{margin:0 0 1em}
.screen-reader-text{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}
:focus-visible{outline:3px solid var(--primary);outline-offset:2px}

/* ============================================
   4. LAYOUT
   ============================================ */
.container{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.content-wrapper{display:grid;grid-template-columns:1fr;gap:32px;max-width:var(--maxw);margin:0 auto;padding:24px}
#main{min-width:0;width:100%}
.page_body{max-width:var(--maxw);margin:0 auto;padding:0 24px}

/* Scroll progress */
.scroll-progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--primary);z-index:9999;transition:width .1s linear}

/* ============================================
   5. HEADER
   ============================================ */
.topbar{background:#06070a;color:#cfd2d8;font-size:12px;border-bottom:1px solid rgba(255,255,255,.06)}
.topbar-inner{max-width:var(--maxw);margin:0 auto;padding:7px 24px;display:flex;justify-content:space-between;align-items:center;gap:12px}
.topbar-date{letter-spacing:.2px}
.topbar a{color:#cfd2d8}
.topbar-search{display:flex;align-items:center;gap:6px}
.topbar-search input{
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);
  color:#fff;border-radius:20px;padding:5px 12px;font-size:12px;width:180px;
}
.topbar-search input::placeholder{color:#9aa0aa}
.topbar-search input:focus{outline:none;border-color:var(--primary);background:rgba(255,255,255,.14)}
.topbar-search button{background:none;border:none;color:#cfd2d8;padding:4px;display:flex;align-items:center}

.header-wrapper{background:var(--header-bg);position:sticky;top:0;z-index:1000;box-shadow:0 2px 10px rgba(0,0,0,.25)}
.header-container{max-width:var(--maxw);margin:0 auto;padding:0 24px;display:flex;align-items:center;justify-content:space-between;height:64px;gap:16px}
.header-left{flex:0 0 auto}
.blog-logo{display:flex;align-items:center;gap:8px;color:var(--header-fg);text-decoration:none}
.blog-logo:hover{text-decoration:none}
.logo-brand{font-family:var(--font-sans);font-size:26px;font-weight:800;letter-spacing:-.5px}
.logo-tv-badge{display:inline-flex;align-items:center;gap:3px;background:var(--primary);color:#fff;padding:3px 8px;border-radius:4px;font-weight:700;font-size:13px;letter-spacing:.5px}
.tv-icon{width:16px;height:16px;fill:currentColor}
.logo-tagline{font-size:11px;color:#8b909a;font-weight:400;margin-left:4px}
.header-right{display:flex;align-items:center;gap:10px}

/* ============================================
   6. NAVIGATION
   ============================================ */
.desktop-nav{flex:1;display:flex;justify-content:flex-end}
.nav-menu{display:flex;list-style:none;gap:2px;align-items:center}
.nav-menu>li>a{display:block;padding:10px 14px;color:var(--header-fg);text-decoration:none;font-family:var(--font-sans);font-size:14px;font-weight:600;letter-spacing:.2px;border-bottom:3px solid transparent;transition:all var(--transition)}
.nav-menu>li>a:hover,.nav-menu>li>a:focus{background:rgba(255,255,255,.08);border-bottom-color:var(--primary);text-decoration:none}
.has-submenu{position:relative}
.has-submenu>a{display:flex;align-items:center;gap:5px}
.dropdown-arrow{font-size:9px;transition:transform var(--transition)}
.submenu{position:absolute;top:100%;left:0;background:#fff;min-width:210px;box-shadow:var(--shadow-lg);border-radius:0 0 var(--radius-sm) var(--radius-sm);border-top:3px solid var(--primary);opacity:0;visibility:hidden;transform:translateY(8px);transition:all var(--transition);z-index:1001;padding:6px 0}
.submenu li a{display:block;padding:10px 16px;color:var(--text);font-size:13px;font-weight:500;font-family:var(--font-sans);border-bottom:none;transition:all var(--transition)}
.submenu li a:hover{background:var(--surface);color:var(--primary);padding-left:22px;text-decoration:none}
.has-submenu:hover .submenu,.has-submenu:focus-within .submenu{opacity:1;visibility:visible;transform:translateY(0)}
.has-submenu:hover .dropdown-arrow{transform:rotate(180deg)}

/* Mobile toggle */
.mobile-menu-toggle{display:none;flex-direction:column;gap:5px;background:none;border:none;padding:8px;z-index:1001}
.mobile-menu-toggle span{display:block;width:24px;height:2px;background:#fff;transition:all var(--transition)}
.mobile-menu-toggle.active span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.mobile-menu-toggle.active span:nth-child(2){opacity:0}
.mobile-menu-toggle.active span:nth-child(3){transform:rotate(-45deg) translate(7px,-6px)}
.mobile-search-btn{display:none;background:none;border:none;color:#fff;padding:6px}

/* Mobile nav */
.mobile-nav-container{display:none;background:var(--header-bg);border-top:1px solid rgba(255,255,255,.08);position:fixed;top:64px;left:0;right:0;bottom:0;overflow-y:auto;z-index:999;padding-bottom:40px}
.mobile-nav-container.active{display:block}
.mobile-nav-menu li{border-bottom:1px solid rgba(255,255,255,.07)}
.mobile-nav-menu li a{display:flex;justify-content:space-between;align-items:center;padding:15px 20px;color:#fff;text-decoration:none;font-size:15px;font-weight:600}
.mobile-nav-menu li a:hover{background:rgba(200,16,46,.2);text-decoration:none}
.has-submenu-mobile>a .dropdown-arrow-mobile{transition:transform var(--transition)}
.has-submenu-mobile.open>a .dropdown-arrow-mobile{transform:rotate(180deg)}
.submenu-mobile{max-height:0;overflow:hidden;background:#11141a;transition:max-height .3s ease}
.submenu-mobile.open{max-height:400px}
.submenu-mobile li a{padding-left:40px;font-size:14px;font-weight:500}
.mobile-search-box{padding:16px 20px;border-bottom:1px solid rgba(255,255,255,.08)}
.mobile-search-box form{display:flex;gap:8px}
.mobile-search-box input{flex:1;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);color:#fff;border-radius:6px;padding:10px 14px;font-size:14px}
.mobile-search-box input::placeholder{color:#9aa0aa}
.mobile-search-box button{background:var(--primary);color:#fff;border:none;border-radius:6px;padding:0 16px;font-weight:600}

/* ============================================
   7. BREAKING NEWS TICKER
   ============================================ */
.breaking-news-bar{background:var(--primary);color:#fff;overflow:hidden;position:relative}
.breaking-news-bar .container{display:flex;align-items:center;max-width:var(--maxw);margin:0 auto;padding:0 24px;height:38px;gap:14px}
.breaking-label{background:#fff;color:var(--primary);padding:3px 11px;font-weight:800;font-size:11px;text-transform:uppercase;letter-spacing:.6px;border-radius:3px;flex-shrink:0;display:flex;align-items:center;gap:5px}
.breaking-dot{width:7px;height:7px;border-radius:50%;background:var(--primary);animation:pulse 1.5s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
.breaking-news-ticker{flex:1;overflow:hidden;white-space:nowrap;mask-image:linear-gradient(90deg,transparent,#000 4%,#000 96%,transparent)}
.breaking-news-ticker .ticker-track{display:inline-block;animation:ticker 30s linear infinite;padding-left:100%}
.breaking-news-ticker a{color:#fff;font-size:13px;font-weight:500;margin-right:42px}
.breaking-news-ticker a:hover{text-decoration:underline}
@keyframes ticker{0%{transform:translateX(0)}100%{transform:translateX(-100%)}}
@media (prefers-reduced-motion:reduce){
  .breaking-news-ticker .ticker-track,.breaking-dot{animation:none}
  .ticker-track{padding-left:0}
}

/* ============================================
   8. HERO / FEATURED
   ============================================ */
.hero-section{position:relative;border-radius:var(--radius);overflow:hidden;margin-bottom:28px;background:#11141a;box-shadow:var(--shadow)}
.hero-image-link{display:block;position:relative}
.hero-image{width:100%;height:100%;object-fit:cover;aspect-ratio:16/9;display:block;transition:transform .6s ease}
.hero-section:hover .hero-image{transform:scale(1.03)}
.hero-section::after{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.92) 0%,rgba(0,0,0,.4) 45%,transparent 75%);pointer-events:none}
.hero-content{position:absolute;left:0;right:0;bottom:0;padding:28px 30px;z-index:2}
.hero-category,.news-card-label a{display:inline-block;background:var(--primary);color:#fff;padding:4px 12px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;border-radius:3px;margin-bottom:12px}
.hero-category:hover,.news-card-label a:hover{background:var(--primary-dark);text-decoration:none}
.hero-title{font-size:30px;line-height:1.2;margin:0 0 8px;max-width:760px}
.hero-title a{color:#fff}
.hero-title a:hover{color:#ffd9df;text-decoration:none}
.hero-excerpt{color:rgba(255,255,255,.85);font-size:15px;margin:0;max-width:620px}
.hero-meta{color:rgba(255,255,255,.7);font-size:12px;margin-top:10px}

/* ============================================
   9. POST CARDS
   ============================================ */
.section-title{font-family:var(--font-sans);font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:1px;color:var(--accent);margin:0 0 18px;padding-bottom:10px;border-bottom:3px solid var(--border);position:relative;display:flex;align-items:center;gap:8px}
.section-title::before{content:'';width:30px;height:3px;background:var(--primary);position:absolute;bottom:-3px;left:0}
.section-title .count{color:var(--muted);font-weight:600}

.blog-posts{display:grid;grid-template-columns:1fr;gap:24px}
.news-card{background:#fff;border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);border:1px solid var(--border);transition:transform var(--transition),box-shadow var(--transition);display:flex;flex-direction:column}
.news-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.news-card-image{position:relative;overflow:hidden;background:var(--surface)}
.news-card-image img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block;transition:transform .5s ease}
.news-card:hover .news-card-image img{transform:scale(1.06)}
.news-card-label{position:absolute;top:12px;left:12px;z-index:2}
.news-card-content{padding:16px 18px 18px;display:flex;flex-direction:column;flex:1}
.news-card-title{font-size:18px;line-height:1.3;margin:0 0 8px;font-family:var(--font-serif)}
.news-card-title a{color:var(--accent)}
.news-card-title a:hover{color:var(--primary);text-decoration:none}
.news-card-snippet{font-size:14px;color:var(--muted);line-height:1.55;margin:0 0 12px;flex:1}
.news-card-footer{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:auto;padding-top:10px;border-top:1px solid var(--border)}
.news-card-date{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px}
.news-card-date::before{content:'';width:6px;height:6px;border-radius:50%;background:var(--primary)}

/* ============================================
   10. ARTICLE PAGE
   ============================================ */
.breadcrumbs{font-size:12px;color:var(--muted);padding:14px 0 0;margin-bottom:8px}
.breadcrumbs a{color:var(--muted);font-weight:600}
.breadcrumbs a:hover{color:var(--primary);text-decoration:none}
.breadcrumbs .sep{margin:0 8px;opacity:.6}
.breadcrumbs .current{color:var(--text);font-weight:600}
.article-header{margin-bottom:20px}
.article-category{display:inline-block;background:var(--primary);color:#fff;padding:4px 12px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;border-radius:3px;margin-bottom:14px}
.article-title{font-size:34px;line-height:1.2;margin:0 0 16px}
.article-meta{display:flex;flex-wrap:wrap;align-items:center;gap:14px;font-size:13px;color:var(--muted);padding-bottom:16px;border-bottom:1px solid var(--border)}
.article-meta .meta-item{display:flex;align-items:center;gap:6px}
.article-meta .meta-item strong{color:var(--text);font-weight:700}
.article-meta .meta-updated{color:var(--primary);font-weight:600}
.article-featured{margin:20px 0 24px;border-radius:var(--radius);overflow:hidden}
.article-featured img{width:100%;display:block;aspect-ratio:16/9;object-fit:cover}
.article-featured figcaption,.image-credit{font-size:12px;color:var(--muted);margin-top:6px;font-style:italic;text-align:center}

/* Article body */
.single-post .post-body.entry-content{font-size:18px;line-height:1.8;color:#2a2c30;max-width:740px;margin:0 auto;padding:0 16px}
.post-body.entry-content p{margin:0 0 1.3em}
.post-body.entry-content h2{font-size:26px;margin:1.4em 0 .6em}
.post-body.entry-content h3{font-size:21px;margin:1.2em 0 .5em}
.post-body.entry-content h4{font-size:18px;margin:1em 0 .4em}
.post-body.entry-content img{max-width:100%;height:auto;border-radius:var(--radius-sm);display:block;margin:1.2em auto}
.post-body.entry-content a{color:var(--primary);text-decoration:underline}
.post-body.entry-content blockquote{border-left:4px solid var(--primary);padding:8px 20px;margin:1.2em 0;color:var(--muted);font-style:italic;background:var(--surface);border-radius:0 var(--radius-sm) var(--radius-sm) 0}
.post-body.entry-content ul,.post-body.entry-content ol{margin:0 0 1.2em;padding-left:1.4em}
.post-body.entry-content ul li,.post-body.entry-content ol li{margin-bottom:.4em}
.post-body.entry-content pre{background:#1a1d24;color:#e8eaed;padding:16px;border-radius:var(--radius-sm);overflow-x:auto;font-size:14px}
.post-body.entry-content figure{margin:1.2em 0}
.post-body.entry-content figure img{margin:0 auto}
.post-body.entry-content hr{border:none;border-top:1px solid var(--border);margin:1.5em 0}
.post-body.entry-content code{background:var(--surface);padding:2px 6px;border-radius:3px;font-family:Consolas,Monaco,'Courier New',monospace;font-size:0.9em}

/* Reading time badge */
.reading-time{display:inline-flex;align-items:center;gap:5px}

/* ============================================
   11. SOCIAL SHARING
   ============================================ */
.share-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:24px 0;padding:16px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
.share-bar-label{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--accent);margin-right:4px}
.share-btn{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;background:var(--surface);color:var(--text);border:1px solid var(--border);transition:all var(--transition)}
.share-btn svg{width:17px;height:17px;fill:currentColor;display:block}
.share-btn span{display:none}
.share-btn:hover{transform:translateY(-3px);text-decoration:none;color:#fff}
.share-btn.facebook:hover{background:#1877f2;border-color:#1877f2}
.share-btn.twitter:hover{background:#000;border-color:#000}
.share-btn.whatsapp:hover{background:#25d366;border-color:#25d366}
.share-btn.telegram:hover{background:#229ed9;border-color:#229ed9}
.share-btn.copylink:hover{background:var(--accent);border-color:var(--accent)}
@media (max-width:480px){.share-btn{width:40px;height:40px}.share-btn svg{width:18px;height:18px}}

/* ============================================
   12. RELATED POSTS / TRENDING
   ============================================ */
.related-posts,.trending-widget{margin-top:32px}
.related-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.related-card a{display:block}
.related-card img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:var(--radius-sm);margin-bottom:8px}
.related-card h4{font-size:15px;line-height:1.3;margin:0;font-family:var(--font-serif)}
.related-card a:hover h4{color:var(--primary);text-decoration:none}
.trending-list{counter-reset:trending}
.trending-list li{counter-increment:trending;display:flex;align-items:flex-start;gap:12px;padding:11px 0;border-bottom:1px solid var(--border)}
.trending-list li:last-child{border-bottom:none}
.trending-list li::before{content:counter(trending,decimal-leading-zero);font-family:var(--font-serif);font-size:20px;font-weight:700;color:var(--primary);min-width:28px}
.trending-list a{font-size:14px;font-weight:600;line-height:1.35;color:var(--accent)}
.trending-list a:hover{color:var(--primary);text-decoration:none}

/* ============================================
   13. SIDEBAR
   ============================================ */
.sidebar-wrapper{width:100%}
.sidebar-wrapper .widget{background:#fff;border:1px solid var(--border);border-radius:var(--radius);padding:18px 20px;margin-bottom:22px;box-shadow:var(--shadow-sm)}
.sidebar-wrapper .widget h2,.sidebar-wrapper .widget h3{font-family:var(--font-sans);font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:.8px;color:var(--accent);margin:0 0 14px;padding-bottom:9px;border-bottom:3px solid var(--border);position:relative}
.sidebar-wrapper .widget h2::before,.sidebar-wrapper .widget h3::before{content:'';position:absolute;bottom:-3px;left:0;width:32px;height:3px;background:var(--primary)}
.sidebar-wrapper .widget ul li{padding:8px 0;border-bottom:1px solid var(--surface)}
.sidebar-wrapper .widget ul li:last-child{border-bottom:none}
.sidebar-wrapper .widget ul li a{font-size:14px;line-height:1.4;color:var(--text);display:block}
.sidebar-wrapper .widget ul li a:hover{color:var(--primary);text-decoration:none}
.sidebar-wrapper .PopularPosts img{border-radius:var(--radius-sm);margin-bottom:6px}
.sidebar-wrapper .PopularPosts .item-title a{font-weight:600;font-size:14px}

/* ============================================
   14. FOOTER
   ============================================ */
.footer{background:#06070a;color:#cfd2d8;padding:50px 0 0;margin-top:40px;border-top:4px solid var(--primary)}
.footer-container{max-width:var(--maxw);margin:0 auto;padding:0 24px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:36px}
.footer-widget h3{color:#fff;font-size:14px;font-weight:800;text-transform:uppercase;letter-spacing:1px;margin:0 0 16px;padding-bottom:10px;position:relative}
.footer-widget h3::after{content:'';position:absolute;bottom:0;left:0;width:36px;height:3px;background:var(--primary);border-radius:2px}
.footer-widget p{color:#9aa0aa;font-size:14px;line-height:1.7;margin:0 0 14px}
.footer-widget ul li{margin-bottom:9px}
.footer-widget ul li a{color:#b9bfc9;font-size:14px;transition:all var(--transition);display:inline-block}
.footer-widget ul li a:hover{color:var(--primary);padding-left:6px;text-decoration:none}
.footer-social{display:flex;gap:10px;margin-top:16px}
.footer-social a{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;background:rgba(255,255,255,.08);border-radius:50%;color:#fff;font-size:15px;transition:all var(--transition)}
.footer-social a:hover{background:var(--primary);transform:translateY(-3px);text-decoration:none}
.footer-social a svg{width:16px;height:16px;fill:currentColor}
.footer-bottom{max-width:var(--maxw);margin:36px auto 0;padding:18px 24px;border-top:1px solid rgba(255,255,255,.08);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-bottom p{color:#7a8089;font-size:13px;margin:0}
.footer-bottom a{color:#b9bfc9}
.footer-bottom a:hover{color:var(--primary);text-decoration:none}
.needs-config{font-size:11px;color:#7a8089;font-style:italic}

/* Attribution */
.Attribution{text-align:center;padding:14px;color:#7a8089;font-size:12px;background:#040508}
.Attribution a{color:#9aa0aa}

/* ============================================
   15. BACK TO TOP, PAGER, MISC
   ============================================ */
.back-to-top{position:fixed;bottom:28px;right:28px;width:46px;height:46px;background:var(--primary);color:#fff;border:none;border-radius:50%;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transform:translateY(16px);transition:all var(--transition);box-shadow:var(--shadow);z-index:998}
.back-to-top svg{width:22px;height:22px;fill:#fff}
.back-to-top.visible{opacity:1;visibility:visible;transform:translateY(0)}
.back-to-top:hover{background:var(--primary-dark);transform:translateY(-3px)}
.blog-pager{display:flex;justify-content:space-between;gap:12px;margin:30px 0;flex-wrap:wrap}
.blog-pager a{background:var(--accent);color:#fff;padding:10px 22px;border-radius:var(--radius-sm);font-size:14px;font-weight:600;transition:all var(--transition)}
.blog-pager a:hover{background:var(--primary);text-decoration:none}
.main-heading{font-family:var(--font-sans);font-size:22px;font-weight:800;margin:0 0 20px}
.post-filter-message{background:var(--surface);border-left:4px solid var(--primary);padding:14px 18px;margin-bottom:20px;border-radius:0 var(--radius-sm) var(--radius-sm) 0;font-size:14px}

/* ============================================
   16. RESPONSIVE BREAKPOINTS
   ============================================ */
@media (min-width:640px){
  .blog-posts{grid-template-columns:1fr 1fr}
}
@media (min-width:992px){
  .content-wrapper{grid-template-columns:1fr 300px;padding:32px 24px}
  .sidebar-wrapper{grid-column:2;position:sticky;top:88px;align-self:start;max-height:none}
}
@media (min-width:1024px){
  .blog-posts{grid-template-columns:1fr 1fr}
  .hero-title{font-size:38px}
}
@media (max-width:991px){
  .desktop-nav{display:none}
  .mobile-menu-toggle{display:flex}
  .topbar-search{display:none}
  .content-wrapper{grid-template-columns:1fr}
  .sidebar-wrapper{grid-column:1}
  .footer-container{grid-template-columns:1fr 1fr}
}
@media (max-width:768px){
  .footer-container{grid-template-columns:1fr;text-align:center}
  .footer-widget h3::after{left:50%;transform:translateX(-50%)}
  .footer-social{justify-content:center}
  .footer-bottom{flex-direction:column;text-align:center}
  .related-grid{grid-template-columns:1fr 1fr}
  .article-title{font-size:26px}
  .post-body.entry-content{font-size:17px}
}
@media (max-width:480px){
  .container,.content-wrapper,.page_body,.header-container,.breaking-news-bar .container{padding-left:16px;padding-right:16px}
  .blog-posts{grid-template-columns:1fr}
  .related-grid{grid-template-columns:1fr}
  .hero-content{padding:18px 18px}
  .hero-title{font-size:22px}
  .article-title{font-size:23px}
  .post-body.entry-content{font-size:17px;line-height:1.7}
  .back-to-top{width:42px;height:42px;bottom:20px;right:20px}
  .topbar-inner{font-size:11px}
}

/* Accessibility */
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
}

/* Layout editor (Blogger) */
body#layout .hidden,body#layout .invisible{display:inherit}
body#layout .navigation{display:none}
body#layout .page{float:right;margin-left:20px;width:55%}
body#layout .hamburger-menu{display:none}
body#layout .content-wrapper{display:block}
body#layout .sidebar-wrapper{display:block;width:100%}

head.b:template-skin:
/* Layout-mode-only overrides for the Blogger editor */
body#layout .breaking-news-bar,
body#layout .topbar,
body#layout .hero-section,
body#layout .footer{display:none}

body.script:
//
(function(){
  'use strict';

  /* ---- Mobile menu ---- */
  var toggle = document.getElementById('mobileMenuToggle');
  var nav = document.getElementById('mobileNavContainer');
  var header = document.getElementById('siteHeader');

  function closeMenu(){
    if(toggle) toggle.classList.remove('active');
    if(nav) nav.classList.remove('active');
    document.body.style.overflow='';
  }
  function openMenu(){
    if(toggle) toggle.classList.add('active');
    if(nav) nav.classList.add('active');
    document.body.style.overflow='hidden';
  }
  if(toggle && nav){
    toggle.addEventListener('click', function(e){
      e.stopPropagation();
      nav.classList.contains('active') ? closeMenu() : openMenu();
    });
    document.addEventListener('click', function(e){
      if(nav.classList.contains('active') && !nav.contains(e.target) && !toggle.contains(e.target)) closeMenu();
    });
  }

  /* ---- Sports mobile accordion ---- */
  var sportsItem = document.getElementById('sportsMobileItem');
  if(sportsItem){
    var sportsLink = sportsItem.querySelector('a');
    var sportsSub = sportsItem.querySelector('.submenu-mobile');
    if(sportsLink && sportsSub){
      sportsLink.addEventListener('click', function(e){
        e.preventDefault();
        sportsItem.classList.toggle('open');
        sportsSub.classList.toggle('open');
      });
    }
  }

  /* ---- ESC closes menu ---- */
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape') closeMenu();
  });

  /* ---- Mobile search toggle ---- */
  var msBtn = document.getElementById('mobileSearchBtn');
  if(msBtn){
    msBtn.addEventListener('click', function(){
      var box = document.querySelector('.mobile-search-box');
      if(box){ box.scrollIntoView(); box.querySelector('input').focus(); }
    });
  }

  /* ---- Scroll progress + back to top ---- */
  var progress = document.getElementById('scrollProgress');
  var toTop = document.getElementById('backToTop');
  window.addEventListener('scroll', function(){
    var st = document.body.scrollTop || document.documentElement.scrollTop;
    var h = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    if(progress) progress.style.width = (h>0 ? (st/h)*100 : 0) + '%';
    if(toTop) toTop.classList.toggle('visible', st > 400);
  }, {passive:true});
  if(toTop){
    toTop.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });
  }

  /* ---- Reading time ---- */
  var body = document.getElementById('post-body') || document.querySelector('.post-body.entry-content');
  var rt = document.getElementById('readingTime');
  if(body && rt){
    var words = (body.innerText || '').trim().split(/\s+/).length;
    var mins = Math.max(1, Math.round(words/200));
    rt.style.display='inline-flex';
    rt.innerHTML = mins + ' min read';
  }

  /* ---- Copy link ---- */
  document.querySelectorAll('.share-btn.copylink').forEach(function(btn){
    btn.addEventListener('click', function(){
      var url = btn.getAttribute('data-url');
      if(navigator.clipboard){
        navigator.clipboard.writeText(url).then(function(){
          btn.title='Copied!'; var t=btn.querySelector('svg'); if(t){t.style.fill='#25d366';}
          setTimeout(function(){ btn.title='Copy link'; if(t){t.style.fill='';} },1500);
        });
      }
    });
  });

  /* ---- Breaking news ticker (dynamic from feed) ---- */
  var ticker = document.getElementById('breakingTicker');
  if(ticker){
    var feed = ticker.getAttribute('data-feed');
    if(feed){
      fetch(feed + '?alt=json&max-results=8')
        .then(function(r){ return r.json(); })
        .then(function(data){
          var entries = (data.feed && data.feed.entry) || [];
          if(!entries.length){ ticker.innerHTML='<span>Welcome to Boogle TV News &#8212; your trusted source for the latest news.</span>'; return; }
          var html = entries.map(function(e){
            var t = (e.title && e.title.$t) || '';
            var u = (e.link || []).filter(function(l){return l.rel==='alternate';})[0] || {};
            u = u.href || '#';
            return '<a href="'+u+'" target="_top">'+t+'</a>';
          }).join('');
          ticker.innerHTML = '<span>'+html+'</span>';
        })
        .catch(function(){
          ticker.innerHTML='<span>Welcome to Boogle TV News &#8212; your trusted source for the latest news.</span>';
        });
    }
  }

  /* ---- Related posts (dynamic from label feed) ---- */
  var rel = document.getElementById('relatedPosts');
  if(rel){
    var label = rel.getAttribute('data-label');
    var home = rel.getAttribute('data-home');
    var current = rel.getAttribute('data-current');
    if(label && home){
      var url = home + 'feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=6';
      fetch(url)
        .then(function(r){ return r.json(); })
        .then(function(data){
          var entries = ((data.feed && data.feed.entry) || []).filter(function(e){
            var u=(e.link||[]).filter(function(l){return l.rel==='alternate';})[0]||{};
            return (u.href||'') !== current;
          }).slice(0,3);
          if(!entries.length){ rel.parentNode.style.display='none'; return; }
          rel.innerHTML = entries.map(function(e){
            var t=(e.title&&e.title.$t)||'';
            var l=(e.link||[]).filter(function(x){return x.rel==='alternate';})[0]||{};
            var u=l.href||'#';
            var img='';
            if(e.media$thumbnail){ img=e.media$thumbnail.url.replace(/\/s72-c\//,'/w400-h225-c/'); }
            else { img='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 16 9%22%3E%3Crect width=%2216%22 height=%229%22 fill=%22%2311141a%22/%3E%3C/svg%3E'; }
            return '<div class="related-card"><a href="'+u+'" target="_top"><img src="'+img+'" alt="'+t.replace(/"/g,'')+'" loading="lazy"/><h4>'+t+'</h4></a></div>';
          }).join('');
        })
        .catch(function(){ rel.parentNode.style.display='none'; });
    }
  }

  /* ---- Close mobile menu on link click ---- */
  if(nav){
    nav.querySelectorAll('a').forEach(function(a){
      a.addEventListener('click', function(){
        if(a.getAttribute('href') && a.getAttribute('href').indexOf('javascript')!==0) closeMenu();
      });
    });
  }
})();
//
